CREATE TABLE "order_cogs" (
	"order_id" text PRIMARY KEY NOT NULL,
	"tenant_id" text DEFAULT 'hofmi' NOT NULL,
	"cogs_zar" integer,
	"absent_item_ids" text[] DEFAULT '{}'::text[] NOT NULL,
	"estimated" boolean,
	"computed_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "order_cogs_amount_or_absent" CHECK ((cogs_zar IS NULL) = (cardinality(absent_item_ids) > 0)),
	CONSTRAINT "order_cogs_nonnegative" CHECK (cogs_zar >= 0)
);
